class Animal:
    def __init__(self, name):
        self.name = name
    def speak(self):
        print(self.name, "садо медиҳад")

class Cat(Animal):
    def __init__(self, name):
        super().__init__(name)
    def speak(self):
        print(self.name, "мяу мекунад")

Cat("Мурка").speak()

